//! Cargo-driven `cryptnet.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is cryptnet-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x767f0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff54000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff54000000u64)),
        o => panic!("cryptnet-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "engine:c:wine_dll_register", "import:wininet", "import:crypt32", "import:shell32", "import:shlwapi", "import:advapi32", "import:ole32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "x86_64" => &["body", "engine:wine", "engine:c:wine_dll_register", "import:wininet", "import:crypt32", "import:shell32", "import:shlwapi", "import:advapi32", "import:ole32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "aarch64" => &["body", "engine:wine", "engine:c:wine_dll_register", "import:wininet", "import:crypt32", "import:shell32", "import:shlwapi", "import:advapi32", "import:ole32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("cryptnet-rust")
        .c_from_compile_db("cryptnet_shims", &["dll/win32/cryptnet/rust_cohab_stub.c"])
        .spec2def("dll/win32/cryptnet/cryptnet.spec", "cryptnet.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/wininet/wininet.spec", "wininet.dll", "wininet")
        .import_lib("dll/win32/crypt32/crypt32.spec", "crypt32.dll", "crypt32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
